            if show_grid && decoration_count > 1 && index + 1 == decoration_count {
                continue;
            }
            decoration_panel += deco.width() + 1;
        }
        if decoration_panel != self.panel_width {
            decoration_panel = self.panel_width;
        }

        if add_header_padding && show_rule {
            writeln!(
                handle,
                "{}",
                self.colors.rule.paint("─".repeat(term_width))
            )?;
